const crypto = require('crypto');
const signature = $node['Webhook'].json.headers['x-hub-signature-256'];
const payload = $node['Webhook'].json.body;
const secret = $credentials.webhookSecret;
const computed = 'sha256=' + crypto.createHmac('sha256', secret).update(JSON.stringify(payload)).digest('hex');
