compare.example_code:
const systemA = $node['Fetch A'].json;
const systemB = $node['Fetch B'].json;

const changes = [];
for (const itemA of systemA) {
  const itemB = systemB.find(b => b.id === itemA.id);
  if (!itemB) {
    changes.push({type: 'create_in_B', data: itemA});
  } else if (new Date(itemA.updated_at) > new Date(itemB.updated_at)) {
    changes.push({type: 'update_B', data: itemA});
  } else if (new Date(itemB.updated_at) > new Date(itemA.updated_at)) {
    changes.push({type: 'update_A', data: itemB});
  }
}

return changes.map(c => ({json: c}));

aggregate.example_code:
const grouped = {};
for (const item of items) {
  const key = item.json.category;
  if (!grouped[key]) {
    grouped[key] = {category: key, total: 0, count: 0};
  }
  grouped[key].total += item.json.amount;
  grouped[key].count++;
}

return Object.values(grouped).map(g => ({
  json: {
    ...g,
    average: g.total / g.count
  }
}));

