reusable_code_snippets.pagination_handler:
const allData = [];
let page = 1;
let hasMore = true;

while (hasMore) {
  const response = await fetch(`${url}?page=${page}&limit=100`);
  allData.push(...response.data);
  hasMore = response.has_more;
  page++;
}

return allData.map(item => ({json: item}));

